export const recognizeInvoiceResponseItemsItemUnitPriceMin = 0;



export const RecognizeInvoiceResponse = zod.object({
  "supplierName": zod.string().nullable(),
  "invoiceNumber": zod.string().nullish(),
  "invoiceDate": zod.coerce.date().nullable(),
  "items": zod.array(zod.object({
  "rawName": zod.string().describe('Название позиции'),
  "quantity": zod.number().gt(recognizeInvoiceResponseItemsItemQuantityExclusiveMin),
  "unitPrice": zod.number().min(recognizeInvoiceResponseItemsItemUnitPriceMin),
  "unit": zod.string().nullish(),
  "productId": zod.number().nullish().describe('Товар каталога'),
  "productName": zod.string().nullish(),
  "matchStatus": zod.enum(['matched', 'unknown', 'ambiguous']).describe('matched — найден товар, unknown — не найден, ambiguous — подходит несколько'),
  "candidates": zod.array(zod.object({
  "productId": zod.number(),
  "productName": zod.string()
})).optional().describe('Варианты каталога при неоднозначном сопоставлении'),
  "recommended": zod.boolean().describe('Позицию можно провести без правок'),
  "issues": zod.array(zod.string()).optional().describe('Причины, по которым позиция требует внимания пользователя'),
  "suggestedName": zod.string().optional().describe('Очищенное от сорта и размера название — заготовка для нового товара'),
  "suggestedAliases": zod.array(zod.string()).optional().describe('Дополнительные варианты названия, встречавшиеся в документе'),
  "suggestedCategory": zod.string().nullish().describe('Категория'),
  "suggestedUnit": zod.string().optional().describe('Единица измерения из документа или по категории'),
  "suggestedMarkupPercent": zod.number().optional().describe('Наценка'),
  "suggestedShelfLifeDays": zod.number().optional().describe('Срок годности')
})),
  "recognized": zod.number().describe('Сколько позиций распознано в документе'),
  "catalogLines": zod.number().describe('Сколько позиций готово к проведению'),
  "warnings": zod.array(zod.string()).optional()
})


